import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { useSocket } from '../hooks/useSocket';
import { initializePushNotifications, requestNotificationPermission, sendPushNotification } from '../utils/pushNotifications';

function AdminDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [users, setUsers] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [services, setServices] = useState([]);
  const [refunds, setRefunds] = useState([]);
  const [selectedRefund, setSelectedRefund] = useState(null);
  const [adminNotes, setAdminNotes] = useState('');
  const [rejectionReason, setRejectionReason] = useState('');
  const [paymentAnalytics, setPaymentAnalytics] = useState({ monthlyRevenue: [], paymentMethods: [], topProviders: [], recentTransactions: [] });
  const [pendingPayouts, setPendingPayouts] = useState({ providerPayouts: [], driverPayouts: [] });
  const [loading, setLoading] = useState(true);
  const [filterRole, setFilterRole] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [darkMode, setDarkMode] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [allReviews, setAllReviews] = useState([]);
  const [reviewsLoading, setReviewsLoading] = useState(false);
  const [promoCodes, setPromoCodes] = useState([]);
  const [showPromoModal, setShowPromoModal] = useState(false);
  const [newPromoCode, setNewPromoCode] = useState({
    code: '', description: '', discountType: 'percentage', discountValue: '', minPurchase: '', usageLimit: '', validUntil: ''
  });
  const [loyaltyLeaderboard, setLoyaltyLeaderboard] = useState([]);
  const [loyaltyStats, setLoyaltyStats] = useState({ totalPoints: 0, totalUsers: 0, averagePoints: 0 });
  const [stats, setStats] = useState({
    users: { total: 0, customers: 0, providers: 0, drivers: 0 },
    services: { total: 0 },
    bookings: { total: 0, completed: 0, pending: 0, cancelled: 0 },
    payments: { totalRevenue: 0, totalCommission: 0, totalProviderPayouts: 0, totalDriverPayouts: 0, totalTransactions: 0, monthlyGrowth: 0, pendingProviderPayouts: 0, pendingDriverPayouts: 0 },
    platform: { rating: 0, totalReviews: 0 }
  });
  const [onlineUsers, setOnlineUsers] = useState({ providers: [], drivers: [] });
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifications, setShowNotifications] = useState(false);
  const [liveActivity, setLiveActivity] = useState([]);

  const adminToken = localStorage.getItem('adminToken');

  const { 
    isConnected,
    onDriverStatusChange,
    onBookingStatusChanged,
    onNewNotification
  } = useSocket();

  useEffect(() => {
    initializePushNotifications();
    fetchAllData();
    fetchOnlineUsers();
    fetchPromoCodes();
    fetchLoyaltyLeaderboard();
    const interval = setInterval(fetchOnlineUsers, 10000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const unsubscribe = onDriverStatusChange((data) => {
      setOnlineUsers(prev => {
        const updatedDrivers = [...prev.drivers];
        if (data.isOnline) {
          if (!updatedDrivers.some(d => d.id === data.driverId)) {
            updatedDrivers.push({ id: data.driverId, name: data.driverName, isOnline: true });
          }
        } else {
          const index = updatedDrivers.findIndex(d => d.id === data.driverId);
          if (index !== -1) updatedDrivers.splice(index, 1);
        }
        return { ...prev, drivers: updatedDrivers };
      });
      setLiveActivity(prev => [{
        id: Date.now(),
        type: 'driver_status',
        message: `${data.driverName || 'A driver'} is now ${data.isOnline ? 'ONLINE' : 'OFFLINE'}`,
        timestamp: new Date()
      }, ...prev].slice(0, 20));
    });
    return () => unsubscribe && unsubscribe();
  }, [onDriverStatusChange]);

  useEffect(() => {
    const unsubscribe = onBookingStatusChanged((data) => {
      fetchStats();
      fetchBookings();
      setLiveActivity(prev => [{
        id: Date.now(),
        type: 'booking_status',
        message: `Booking #${data.bookingId?.slice(-6)} status changed to ${data.status}`,
        timestamp: new Date()
      }, ...prev].slice(0, 20));
    });
    return () => unsubscribe && unsubscribe();
  }, [onBookingStatusChanged]);

  useEffect(() => {
    const unsubscribe = onNewNotification((notification) => {
      setNotifications(prev => [notification, ...prev]);
      setUnreadCount(prev => prev + 1);
      setLiveActivity(prev => [{
        id: Date.now(),
        type: 'notification',
        message: notification.message,
        timestamp: new Date()
      }, ...prev].slice(0, 20));
    });
    return () => unsubscribe && unsubscribe();
  }, [onNewNotification]);

  const fetchOnlineUsers = async () => {
    try {
      const driversRes = await fetch('http://localhost:5000/api/driver/online');
      const driversData = await driversRes.json();
      if (driversData.success) {
        setOnlineUsers(prev => ({ ...prev, drivers: driversData.drivers || [] }));
      }
    } catch (error) {
      console.error('Error fetching online users:', error);
    }
  };

  const fetchAllData = async () => {
    setLoading(true);
    try {
      await Promise.all([
        fetchStats(),
        fetchUsers(),
        fetchBookings(),
        fetchServices(),
        fetchPaymentAnalytics(),
        fetchPendingPayouts(),
        fetchRefunds(),
        fetchAllReviews()
      ]);
    } catch (error) {
      console.error('Error:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/admin/stats', {
        headers: { 'Authorization': `Bearer ${adminToken}` }
      });
      const data = await res.json();
      if (data.success) setStats(data.stats);
    } catch (error) { console.error(error); }
  };

  const fetchUsers = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/admin/users', {
        headers: { 'Authorization': `Bearer ${adminToken}` }
      });
      const data = await res.json();
      if (data.success) setUsers(data.users);
    } catch (error) { console.error(error); }
  };

  const fetchBookings = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/admin/bookings', {
        headers: { 'Authorization': `Bearer ${adminToken}` }
      });
      const data = await res.json();
      if (data.success) setBookings(data.bookings);
    } catch (error) { console.error(error); }
  };

  const fetchServices = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/admin/services', {
        headers: { 'Authorization': `Bearer ${adminToken}` }
      });
      const data = await res.json();
      if (data.success) setServices(data.services);
    } catch (error) { console.error(error); }
  };

  const fetchPaymentAnalytics = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/admin/payment-analytics', {
        headers: { 'Authorization': `Bearer ${adminToken}` }
      });
      const data = await res.json();
      if (data.success) setPaymentAnalytics(data.analytics);
    } catch (error) { console.error(error); }
  };

  const fetchPendingPayouts = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/admin/pending-payouts', {
        headers: { 'Authorization': `Bearer ${adminToken}` }
      });
      const data = await res.json();
      if (data.success) setPendingPayouts(data);
    } catch (error) { console.error(error); }
  };

  const fetchRefunds = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/refunds/all', {
        headers: { 'Authorization': `Bearer ${adminToken}` }
      });
      const data = await res.json();
      if (data.success) setRefunds(data.refunds);
    } catch (error) { console.error(error); }
  };

  const fetchAllReviews = async () => {
    setReviewsLoading(true);
    try {
      const res = await fetch('http://localhost:5000/api/reviews/all', {
        headers: { 'Authorization': `Bearer ${adminToken}` }
      });
      const data = await res.json();
      if (data.success) setAllReviews(data.reviews);
    } catch (error) {
      console.error('Error fetching reviews:', error);
    } finally {
      setReviewsLoading(false);
    }
  };

  const hideReview = async (reviewId) => {
    if (window.confirm('Hide this review?')) {
      try {
        const res = await fetch(`http://localhost:5000/api/reviews/hide/${reviewId}`, {
          method: 'PUT',
          headers: { 'Authorization': `Bearer ${adminToken}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success('Review hidden');
          fetchAllReviews();
        }
      } catch (error) {
        toast.error('Failed to hide review');
      }
    }
  };

  const fetchPromoCodes = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/promo/all', {
        headers: { 'Authorization': `Bearer ${adminToken}` }
      });
      const data = await res.json();
      if (data.success) setPromoCodes(data.promoCodes);
    } catch (error) {
      console.error('Error fetching promo codes:', error);
    }
  };

  const createPromoCode = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/promo/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${adminToken}`
        },
        body: JSON.stringify({
          ...newPromoCode,
          discountValue: parseFloat(newPromoCode.discountValue),
          minPurchase: parseFloat(newPromoCode.minPurchase) || 0,
          usageLimit: parseInt(newPromoCode.usageLimit) || 1
        })
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Promo code created!');
        setShowPromoModal(false);
        setNewPromoCode({
          code: '', description: '', discountType: 'percentage', discountValue: '', minPurchase: '', usageLimit: '', validUntil: ''
        });
        fetchPromoCodes();
      } else {
        toast.error(data.error || 'Failed to create promo code');
      }
    } catch (error) {
      toast.error('Failed to create promo code');
    }
  };

  const deletePromoCode = async (id, code) => {
    if (window.confirm(`Delete promo code "${code}"?`)) {
      try {
        const res = await fetch(`http://localhost:5000/api/promo/${id}`, {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${adminToken}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success('Promo code deleted');
          fetchPromoCodes();
        }
      } catch (error) {
        toast.error('Failed to delete promo code');
      }
    }
  };

  const fetchLoyaltyLeaderboard = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/loyalty/leaderboard');
      const data = await res.json();
      if (data.success) {
        setLoyaltyLeaderboard(data.leaderboard);
        const totalPoints = data.leaderboard.reduce((sum, l) => sum + l.lifetimePoints, 0);
        setLoyaltyStats({
          totalPoints,
          totalUsers: data.leaderboard.length,
          averagePoints: data.leaderboard.length > 0 ? Math.round(totalPoints / data.leaderboard.length) : 0
        });
      }
    } catch (error) {
      console.error('Error fetching loyalty leaderboard:', error);
    }
  };

  const updateUserStatus = async (userId, isActive) => {
    try {
      const res = await fetch(`http://localhost:5000/api/admin/users/${userId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${adminToken}` },
        body: JSON.stringify({ isActive })
      });
      if (res.ok) {
        toast.success(`User ${isActive ? 'activated' : 'suspended'}`);
        fetchUsers();
        fetchStats();
      }
    } catch (error) {
      toast.error('Failed to update user');
    }
  };

  const verifyUser = async (userId, role) => {
    try {
      const res = await fetch(`http://localhost:5000/api/admin/users/${userId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${adminToken}` },
        body: JSON.stringify({ isVerified: true })
      });
      if (res.ok) {
        toast.success(`${role} verified successfully`);
        fetchUsers();
      }
    } catch (error) {
      toast.error('Failed to verify');
    }
  };

  const deleteUser = async (userId, name) => {
    if (window.confirm(`Delete ${name}? This action cannot be undone.`)) {
      try {
        await fetch(`http://localhost:5000/api/admin/users/${userId}`, {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${adminToken}` }
        });
        toast.success('User deleted');
        fetchUsers();
        fetchStats();
      } catch (error) {
        toast.error('Failed to delete');
      }
    }
  };

  const toggleServiceStatus = async (serviceId, isActive) => {
    try {
      await fetch(`http://localhost:5000/api/admin/services/${serviceId}/status`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${adminToken}` },
        body: JSON.stringify({ isActive: !isActive })
      });
      toast.success(`Service ${!isActive ? 'activated' : 'hidden'}`);
      fetchServices();
    } catch (error) {
      toast.error('Failed to update');
    }
  };

  const processPayout = async (userId, type) => {
    try {
      await fetch('http://localhost:5000/api/admin/process-payout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${adminToken}` },
        body: JSON.stringify({ userId, type })
      });
      toast.success('Payout processed');
      fetchPendingPayouts();
      fetchStats();
    } catch (error) {
      toast.error('Failed to process payout');
    }
  };

  const approveRefund = async (refundId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/refunds/${refundId}/approve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${adminToken}` },
        body: JSON.stringify({ adminNotes })
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Refund approved!');
        fetchRefunds();
        setSelectedRefund(null);
        setAdminNotes('');
      } else {
        toast.error(data.error || 'Failed to approve refund');
      }
    } catch (error) {
      toast.error('Failed to approve refund');
    }
  };

  const rejectRefund = async (refundId) => {
    if (!rejectionReason) {
      toast.error('Please provide a rejection reason');
      return;
    }
    try {
      const res = await fetch(`http://localhost:5000/api/refunds/${refundId}/reject`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${adminToken}` },
        body: JSON.stringify({ rejectionReason })
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Refund rejected');
        fetchRefunds();
        setSelectedRefund(null);
        setRejectionReason('');
      } else {
        toast.error(data.error || 'Failed to reject refund');
      }
    } catch (error) {
      toast.error('Failed to reject refund');
    }
  };

  const downloadInvoice = async (transactionId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/invoices/download/${transactionId}`, {
        headers: { 'Authorization': `Bearer ${adminToken}` }
      });
      if (res.ok) {
        const blob = await res.blob();
        const url = window.URL.createObjectURL(blob);
        window.open(url, '_blank');
        setTimeout(() => window.URL.revokeObjectURL(url), 100);
        toast.success('Invoice opened');
      } else {
        toast.error('Failed to download invoice');
      }
    } catch (err) {
      toast.error('Error downloading invoice');
    }
  };

  const getRoleBadge = (role) => {
    const config = {
      customer: { bg: '#d1fae5', color: '#065f46', icon: '👤', label: 'Customer' },
      provider: { bg: '#e0e7ff', color: '#4338ca', icon: '🔧', label: 'Provider' },
      driver: { bg: '#fef3c7', color: '#92400e', icon: '🚗', label: 'Driver' },
      admin: { bg: '#f3e8ff', color: '#7c3aed', icon: '👑', label: 'Admin' }
    };
    const c = config[role] || { bg: '#f3f4f6', color: '#6b7280', icon: '❓', label: role };
    return <span style={{ backgroundColor: c.bg, color: c.color, padding: '4px 10px', borderRadius: '20px', fontSize: '11px', display: 'inline-flex', alignItems: 'center', gap: '4px' }}>{c.icon} {c.label}</span>;
  };

  const getStatusBadge = (status) => {
    const config = {
      pending: { bg: '#fef3c7', color: '#92400e', icon: '⏳', label: 'Pending' },
      confirmed: { bg: '#d1fae5', color: '#065f46', icon: '✅', label: 'Confirmed' },
      'in-progress': { bg: '#e0e7ff', color: '#4338ca', icon: '🔧', label: 'In Progress' },
      completed: { bg: '#d1fae5', color: '#065f46', icon: '✔️', label: 'Completed' },
      cancelled: { bg: '#fee2e2', color: '#991b1b', icon: '❌', label: 'Cancelled' }
    };
    const c = config[status] || { bg: '#f3f4f6', color: '#6b7280', icon: '📌', label: status };
    return <span style={{ backgroundColor: c.bg, color: c.color, padding: '4px 10px', borderRadius: '20px', fontSize: '11px', display: 'inline-flex', alignItems: 'center', gap: '4px' }}>{c.icon} {c.label}</span>;
  };

  const getRefundStatusBadge = (status) => {
    const config = {
      pending: { bg: '#fef3c7', color: '#92400e', text: 'Pending' },
      approved: { bg: '#d1fae5', color: '#065f46', text: 'Approved' },
      rejected: { bg: '#fee2e2', color: '#991b1b', text: 'Rejected' },
      completed: { bg: '#d1fae5', color: '#065f46', text: 'Completed' }
    };
    const c = config[status] || { bg: '#f3f4f6', color: '#6b7280', text: status };
    return <span style={{ backgroundColor: c.bg, color: c.color, padding: '4px 8px', borderRadius: '20px', fontSize: '11px' }}>{c.text}</span>;
  };

  const getStripeBadge = (status) => {
    if (!status) return <span style={{ backgroundColor: '#f3f4f6', color: '#6b7280', padding: '4px 8px', borderRadius: '20px', fontSize: '11px' }}>Not Connected</span>;
    if (status === 'active') return <span style={{ backgroundColor: '#d1fae5', color: '#065f46', padding: '4px 8px', borderRadius: '20px', fontSize: '11px' }}>Connected</span>;
    if (status === 'pending') return <span style={{ backgroundColor: '#fef3c7', color: '#92400e', padding: '4px 8px', borderRadius: '20px', fontSize: '11px' }}>Pending</span>;
    return <span style={{ backgroundColor: '#fee2e2', color: '#991b1b', padding: '4px 8px', borderRadius: '20px', fontSize: '11px' }}>Rejected</span>;
  };

  const filteredUsers = users.filter(u => {
    const matchesRole = filterRole === 'all' || u.role === filterRole;
    const matchesSearch = searchTerm === '' || u.email?.toLowerCase().includes(searchTerm.toLowerCase()) || u.firstName?.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesRole && matchesSearch;
  });

  const filteredBookings = bookings.filter(b => {
    const matchesStatus = filterStatus === 'all' || b.status === filterStatus;
    const matchesSearch = searchTerm === '' || b.serviceName?.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesStatus && matchesSearch;
  });

  const maxRevenue = Math.max(...(paymentAnalytics.monthlyRevenue?.map(m => m.revenue) || [0]), 1);
  const pendingRefunds = refunds.filter(r => r.status === 'pending').length;

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: '📊', color: '#8b5cf6' },
    { id: 'users', label: 'Users', icon: '👥', color: '#3b82f6' },
    { id: 'providers', label: 'Providers', icon: '🔧', color: '#10b981' },
    { id: 'drivers', label: 'Drivers', icon: '🚗', color: '#f59e0b' },
    { id: 'bookings', label: 'Bookings', icon: '📅', color: '#ec4899' },
    { id: 'services', label: 'Services', icon: '🛠️', color: '#14b8a6' },
    { id: 'revenue', label: 'Revenue', icon: '💰', color: '#22c55e' },
    { id: 'payouts', label: 'Payouts', icon: '💸', color: '#ef4444' },
    { id: 'refunds', label: 'Refunds', icon: '🔄', color: '#f97316' },
    { id: 'reviews', label: 'Reviews', icon: '⭐', color: '#f59e0b' },
    { id: 'promos', label: 'Promo Codes', icon: '🎟️', color: '#06b6d4' },
    { id: 'loyalty', label: 'Loyalty', icon: '💎', color: '#8b5cf6' }
  ];

  const styles = {
    container: { display: 'flex', minHeight: '100vh', backgroundColor: darkMode ? '#0f172a' : '#f3f4f6' },
    sidebar: {
      width: sidebarCollapsed ? '80px' : '280px',
      backgroundColor: darkMode ? '#1e293b' : '#ffffff',
      transition: 'width 0.3s ease',
      position: 'fixed', height: '100vh', overflow: 'hidden', zIndex: 100, boxShadow: '2px 0 8px rgba(0,0,0,0.05)'
    },
    sidebarHeader: {
      padding: sidebarCollapsed ? '20px 0' : '24px 24px',
      borderBottom: '1px solid ' + (darkMode ? '#334155' : '#e5e7eb'),
      display: 'flex', alignItems: 'center', justifyContent: sidebarCollapsed ? 'center' : 'space-between'
    },
    logoIcon: { fontSize: '28px' },
    logoText: { fontSize: '18px', fontWeight: 'bold', marginLeft: '10px', display: sidebarCollapsed ? 'none' : 'block', color: darkMode ? 'white' : '#1f2937' },
    collapseBtn: { background: 'none', border: 'none', cursor: 'pointer', fontSize: '18px', display: sidebarCollapsed ? 'none' : 'block', color: darkMode ? 'white' : '#6b7280' },
    sidebarMenu: { flex: 1, padding: '20px 0' },
    menuItem: {
      display: 'flex', alignItems: 'center', gap: '12px',
      padding: sidebarCollapsed ? '12px 0' : '12px 24px', margin: '4px 8px', borderRadius: '10px', cursor: 'pointer',
      transition: 'all 0.2s ease', justifyContent: sidebarCollapsed ? 'center' : 'flex-start',
      color: darkMode ? '#94a3b8' : '#6b7280'
    },
    menuItemActive: { backgroundColor: darkMode ? '#8b5cf620' : '#8b5cf610', color: '#8b5cf6' },
    menuIcon: { fontSize: '20px' },
    menuLabel: { fontSize: '14px', fontWeight: '500', display: sidebarCollapsed ? 'none' : 'block' },
    mainContent: { flex: 1, marginLeft: sidebarCollapsed ? '80px' : '280px', transition: 'margin-left 0.3s ease' },
    topHeader: {
      backgroundColor: darkMode ? '#1e293b' : '#ffffff', padding: '16px 30px',
      display: 'flex', justifyContent: 'space-between', alignItems: 'center',
      borderBottom: '1px solid ' + (darkMode ? '#334155' : '#e5e7eb'), position: 'sticky', top: 0, zIndex: 99
    },
    headerTitle: { fontSize: '20px', fontWeight: 'bold', color: darkMode ? 'white' : '#1f2937' },
    headerRight: { display: 'flex', alignItems: 'center', gap: '20px' },
    notificationIcon: { position: 'relative', cursor: 'pointer', fontSize: '22px' },
    notificationBadge: { position: 'absolute', top: '-8px', right: '-8px', backgroundColor: '#ef4444', color: 'white', fontSize: '10px', padding: '2px 6px', borderRadius: '10px' },
    themeToggle: { background: 'none', border: 'none', fontSize: '20px', cursor: 'pointer', padding: '8px', borderRadius: '8px', backgroundColor: darkMode ? '#334155' : '#f3f4f6' },
    wsBadge: { backgroundColor: isConnected ? '#10b981' : '#ef4444', padding: '4px 12px', borderRadius: '20px', fontSize: '11px', color: 'white', display: 'flex', alignItems: 'center', gap: '5px' },
